def reverse_words(sentence):
    w = sentence.split(' ')
    l = len(w)
    r = [''] * l
    for i in range(l):
        r[i] = w[l - 1 - i]
    s = ""
    for j in range(l):
        s += r[j]
        if j < l - 1:
            s += " "
    return s

